import React from "react";
import "bootstrap/dist/css/bootstrap.min.css";
import "bootstrap/dist/js/bootstrap.bundle.min";
import { Button, MantineProvider } from "@mantine/core";

function GroupNavBar() {
  return (
    <div
      id="group-bar"
      className="bg-white rounded-3 d-flex p-3 justify-content-between mb-4 container"
    >
      <h4 className="fw-semibold">Groups management</h4>
      {/* <button className="btn btn-primary btn-sm">Create New Group</button> */}
      <MantineProvider>
        <Button color="purple" variant="filled">
          Create New Group
        </Button>
      </MantineProvider>
    </div>
  );
}

export default GroupNavBar;
